                step,
                randShuffle,
                randOutcome
            );

            seed = uint256(
                keccak256(
                    abi.encode(
                        seed,
                        randShuffle,
                        randOutcome
                    )
                )
            );
        }

        address champion = round[0];
        address runnerUp = finalRunnerUp;

        uint256 championPrize =
            (pool * FIRST_PLACE_BP) / 10000;

        uint256 runnerUpPrize =
            (pool * SECOND_PLACE_BP) / 10000;

        token.send(champion, championPrize, "");
        token.send(runnerUp, runnerUpPrize, "");

        emit Finished(
            cycleId,
            champion,
            runnerUp,
            championPrize,
            runnerUpPrize
        );

        _reset();
    }

    // =====================================================
    // ROUND
    // =====================================================

    function _nextRound(
        address[] memory playersInput,
        uint8 step,
        uint256 randShuffle,
        uint256 randOutcome
    )
        internal
        returns (address[] memory)
    {

        uint256 n = playersInput.length;

        // ================= SHUFFLE =================

        address[] memory shuffled = playersInput;

        for (uint256 i = n; i > 1; i--) {

            uint256 j =
                uint256(
                    keccak256(
                        abi.encode(randShuffle, i)
                    )
                ) % i;

            address tmp = shuffled[i - 1];

            shuffled[i - 1] = shuffled[j];
            shuffled[j] = tmp;
        }

        uint256 nextSize = n / 2;

        address[] memory winners =
            new address[](nextSize);

        address[] memory losers =
            new address[](nextSize);

        // ================= COEFFICIENT =================

        uint256 coeff;

        for (uint256 i = 0; i < n; i++) {
            coeff += uint160(shuffled[i]);
        }

        coeff = coeff % 997;

        // ================= MATCHES =================

        for (uint256 i = 0; i < nextSize; i++) {

            address p1 = shuffled[2 * i];
            address p2 = shuffled[(2 * i) + 1];

            uint256 entropy =
                uint256(
                    keccak256(
                        abi.encode(
                            randOutcome,
                            coeff,
                            step,
                            i,
                            p1,
                            p2
                        )
                    )
                );

            uint256 base = entropy % 1000;

            uint256 a = uint160(p1) % 100;
            uint256 b = uint160(p2) % 100;

            int256 scoreSigned =
                int256(base)
                + int256(a)
                - int256(b);

            uint256 score =
                scoreSigned < 0
                    ? uint256(-scoreSigned)
                    : uint256(scoreSigned);

            uint256 threshold = coeff / 2;

            bool p1wins;

            if ((entropy & 1) == 0) {

                p1wins = score >= threshold;

            } else {

                p1wins = score <= threshold;
            }

            if (p1wins) {

                winners[i] = p1;
                losers[i] = p2;

            } else {

                winners[i] = p2;
                losers[i] = p1;
            }
        }

        // FINAL ROUND (2 players -> 1 winner + 1 runner-up)

        if (n == 2) {
            finalRunnerUp = losers[0];
        }

        emit RoundResolved(
            cycleId,
            step,
            shuffled,
            winners,
            losers
        );

        return winners;
    }

    // =====================================================
    // RESET
    // =====================================================

    function _reset() internal {

        for (uint256 i = 0; i < players.length; i++) {
            joined[players[i]] = false;
        }

        delete players;

        playersCount = 0;

        pool = 0;

        finalRunnerUp = address(0);

        cycleId++;

        state = State.OPEN;
    }
