    for (uint256 i = 0; i < players.length; i++) {

        joined[players[i]] = false;

        isSeller[players[i]] = false;

        isBuyer[players[i]] = false;

        seatSwap[players[i]] = address(0);
        buyerMatched[players[i]] = false;
