// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

import ".deps/github/OpenZeppelin/openzeppelin-contracts/contracts/security/ReentrancyGuard.sol";
import ".deps/github/OpenZeppelin/openzeppelin-contracts/contracts/token/ERC777/ERC777.sol";

interface IVRFGenerator {
    function requestBatch() external;
    function consumeRandom() external returns (uint256);
    function queueSize() external view returns (uint256);
}

contract GarettoTournament_7Step128 is IERC777Recipient, ReentrancyGuard {
    IERC1820Registry private constant _ERC1820_REGISTRY =
        IERC1820Registry(0x1820a4B7618BdE71Dce8cdc73aAB6C95905faD24);

    address public owner;
    ERC777 public immutable token;
    IVRFGenerator public generator;

    uint256 public constant BET = 299.4 ether;
    uint256 public constant SellBET = 329.34 ether;
    uint256 public constant BuyBET = 1676.64 ether;
    uint256 public constant BuyOrSellBET = 1706.58 ether;

    uint256 public constant MAX_PLAYERS = 128;
    uint8 public constant MARKET_STEP = 4;

    enum State {
        OPEN,
        LOCKED
    }

    // Roles used purely for claim bookkeeping / event labeling.
    enum ClaimRole {
        FAILED_BUYER_REFUND,
        CHAMPION,
        RUNNER_UP,
        THIRD,
        FOURTH
    }

    State public state;
    address[] public sellers;
    address[] public buyers;
    address[] public players;
    address[] public postMarketFinalists;
    address[] public failedBuyers;
    address[] public failedSellers;
    address[] public matchedBuyers;
    address[] public matchedSellers;
    address[] public lastRoundLosers;
    address[] public lastRoundWinners;
    address[] public semiFinalLosers;
    address[] public finalLosers;
    mapping(address => address) public seatSwap;
    // Reverse lookup: buyer => seller they were matched with in the market phase.
    // Replaces the O(players.length) scan that used to run per matched buyer in _settleTrades.
    mapping(address => address) public buyerToSeller;
    mapping(address => bool) public isSeller;
    mapping(address => bool) public isBuyer;
    mapping(address => bool) public buyerMatched;
    mapping(address => bool) public joined;
    mapping(address => bool) public wasEliminated;
    address[] public allLosers;
    uint256 public tradersReserve;

    uint256 public playersCount;
    uint256 public pool;
    uint256 public cycleId;

    bool public tradingDone;

    // Claimable balance per address, persists across cycles indefinitely
    // (never touched by _reset()).
    mapping(address => uint256) public claimableBalance;

    event Joined(address indexed player, uint256 indexed cycleId, uint256 playersCount);
    event Received(address indexed from, uint256 amount);
    event RoundResolved(
        uint256 indexed cycleId,
        uint8 indexed step,
        address[] shuffledPlayers,
        address[] winners,
        address[] losers
    );
   event SellerRegistered(
    uint256 indexed cycleId,
    address indexed seller,
    uint256 totalSellers
);

event BuyerRegistered(
    uint256 indexed cycleId,
    address indexed buyer,
    uint256 totalBuyers
);

event TradeMatched(
    uint256 indexed cycleId,
    address indexed seller,
    address indexed buyer
);

event BuyerRefunded(
    uint256 indexed cycleId,
    address indexed buyer,
    uint256 amount
);

event SellerUnmatched(
    uint256 indexed cycleId,
    address indexed seller
);

event TradingPhaseStarted(
    uint256 indexed cycleId
);

event TradingPairFormed(
    uint256 indexed cycleId,
    uint256 indexed pairId,
    address indexed seller,
    address buyer
);

event TradingPhaseFinished(
    uint256 indexed cycleId,
    uint256 matchedTrades
);
    event Finished(uint256 indexed cycleId, address indexed winner, uint256 prize);

    // Fired the moment a payout is credited (during _resolve()'s finalization),
    // before the recipient has withdrawn it.
    event ClaimableCredited(
        address indexed account,
        uint256 indexed cycleId,
        ClaimRole role,
        uint256 amount
    );

    // Fired when the recipient actually pulls funds out via claim().
    // Note: a single claim() call can flush credits accumulated across multiple
    // cycles/roles at once, so this reports the TOTAL withdrawn at claim time,
    // not a single cycle/role. Use ClaimableCredited (above) to reconstruct the
    // per-cycle, per-role breakdown.
    event Claimed(
        address indexed account,
        uint256 totalAmount
    );

    event MarketPhaseResolved(
        uint256 indexed cycleId,
        uint256 matches,
        address[] sellers,
        address[] buyers,
        address[] matchedSellers,
        address[] matchedBuyers,
        address[] failedSellers,
        address[] failedBuyers,
        address[] postMarketFinalists
    );

    constructor(ERC777 _token, address _generator) {
        _ERC1820_REGISTRY.setInterfaceImplementer(
            address(this),
            keccak256("ERC777TokensRecipient"),
            address(this)
        );

        owner = msg.sender;
        token = _token;
        generator = IVRFGenerator(_generator);
        cycleId = 1;
        state = State.OPEN;
    }

       function _isContract(address account) internal view returns (bool) {
        uint256 size;
        assembly {
            size := extcodesize(account)
        }
        return size > 0;
    }


    modifier onlyValidToken() {
        require(msg.sender == address(token), "Invalid token");
        _;
    }
   function tokensReceived(
    address,
    address from,
    address,
    uint256 amount,
    bytes calldata,
    bytes calldata
) external override onlyValidToken nonReentrant
    {
        require(from != address(0), "Invalid sender");
        require(!_isContract(from), "EOA only");
        require(state == State.OPEN, "not open");
        require(playersCount < MAX_PLAYERS, "full");
        require(!joined[from], "already joined");
        require(amount == BET || amount == SellBET || amount == BuyBET || amount == BuyOrSellBET, "must send exact bet");

    emit Received(from, amount);

    // ================= NORMAL JOIN =================
    if (amount == BET) {
        // 299.4 - 29.94 = 269.46
        uint256 generatorFee = 29.94 ether;
        uint256 contribution = 269.46 ether;

        token.send(address(generator), generatorFee, "");

        pool += contribution;

        _join(from);
    }

    // ================= POTENTIAL SELLER =================
    else if (amount == SellBET) {

          //1676.64 - 269.46 - 29.94 = 29.94
        uint256 generatorFee = 29.94 ether;
        uint256 contribution = 269.46 ether;
        uint256 reserveAmount = 29.94 ether;

        token.send(address(generator), generatorFee, "");

        pool += contribution;

        tradersReserve += reserveAmount;

       isSeller[from] = true;

        sellers.push(from);

        emit SellerRegistered(
            cycleId,
            from,
            sellers.length
        );

        _join(from);
    }

    // ================= POTENTIAL BUYER =================
    else if (amount == BuyBET) {

            //1676.64 - 269.46 - 29.94 = 1,377.24
        uint256 generatorFee = 29.94 ether;
        uint256 contribution = 269.46 ether;

        uint256 reserveAmount = 1377.24 ether;

        token.send(address(generator), generatorFee, "");

        pool += contribution;

        tradersReserve += reserveAmount;

       isBuyer[from] = true;

        buyers.push(from);

        emit BuyerRegistered(
            cycleId,
            from,
            buyers.length
        );

        _join(from);
    }
    // ================= POTENTIAL BUYER OR SELLER =================
    else if (amount == BuyOrSellBET) {

           //1706.58 - 269.46 - 29.94 = 1407.18
        uint256 generatorFee = 29.94 ether;
        uint256 contribution = 269.46 ether;

        uint256 reserveAmount = 1407.18 ether;



        token.send(address(generator), generatorFee, "");

        pool += contribution;

        tradersReserve += reserveAmount;

       isBuyer[from] = true;

        buyers.push(from);
          isSeller[from] = true;

        sellers.push(from);
        emit BuyerRegistered(
            cycleId,
            from,
            buyers.length
        );
         emit SellerRegistered(
            cycleId,
            from,
            sellers.length
        );

        _join(from);
    }
    else {
        revert("invalid amount");
    }
}

 function _join(address from) internal {

    require(playersCount < MAX_PLAYERS, "full");
    require(!joined[from], "already joined");

    players.push(from);

    joined[from] = true;

    playersCount++;

    emit Joined(from, cycleId, playersCount);

    if (playersCount == MAX_PLAYERS) {

        state = State.LOCKED;

        _resolve();
    }
}

function _shufflePlayers(
    address[] memory input,
    uint256 randomSeed
) internal pure returns (address[] memory) {

    uint256 n = input.length;
    address[] memory shuffled = new address[](n);

    for (uint256 i = 0; i < n; i++) {
        shuffled[i] = input[i];
    }

    for (uint256 i = n; i > 1; i--) {
        uint256 j = uint256(
            keccak256(abi.encode(randomSeed, i))
        ) % i;

        address tmp = shuffled[i - 1];
        shuffled[i - 1] = shuffled[j];
        shuffled[j] = tmp;
    }

    return shuffled;
}
   // ================= RESOLUTION =================

function _resolve() internal {
    require(state == State.LOCKED, "not locked");

    // Require enough VRF random numbers
    if (generator.queueSize() < 3) {
        generator.requestBatch();
        revert("VRF not ready");
    }

    // =========================================================
    // 3 TRUE RANDOM NUMBERS
    // =========================================================

    // 1. Shuffle full players list
    uint256 randPlayers = generator.consumeRandom();

    // 2. Shuffle each stage internally
    uint256 randStages = generator.consumeRandom();

    // 3. Shuffle pairs / outcomes
    uint256 randPairs = generator.consumeRandom();

    // =========================================================
    // INITIAL FULL SHUFFLE
    // =========================================================

    address[] memory round = _shufflePlayers(
        players,
        randPlayers
    );

    // =========================================================
    // TOURNAMENT STEPS
    // =========================================================

    for (uint8 step = 1; step <= 8; step++) {

        // ================= MARKET STEP =================
        if (step == MARKET_STEP) {

            _marketPhase(round);

            round = _shufflePlayers(
                postMarketFinalists,
                uint256(
                    keccak256(
                        abi.encode(randStages, step)
                    )
                )
            );

            continue;
        }

        // =====================================================
        // RANDOMS FOR CURRENT STEP
        // =====================================================

        uint256 stepShuffle = uint256(
            keccak256(
                abi.encode(
                    randStages,
                    step,
                    round.length
                )
            )
        );

        uint256 stepPairs = uint256(
            keccak256(
                abi.encode(
                    randPairs,
                    step,
                    round.length
                )
            )
        );

        // =====================================================
        // SHUFFLE CURRENT ROUND
        // =====================================================

        round = _shufflePlayers(
            round,
            stepShuffle
        );

        // =====================================================
        // RESOLVE ROUND
        // =====================================================

        address[] memory next = _nextRound(
            round,
            step,
            stepShuffle,
            stepPairs
        );

        // ================= TRACK LOSERS =================

        if (step == 7) {
            semiFinalLosers = lastRoundLosers;
        }

        if (step == 8) {
            finalLosers = lastRoundLosers;
        }

        round = next;
    }

    // =========================================================
    // FINALIZATION
    // =========================================================

    _settleTrades();

    // round[0] = champion
    // round[1] = runner up

    _distributePrizes(
        round[0],
        round[1]
    );

    _reset();
}

    // ================= ROUND =================

function _nextRound(
    address[] memory playersInput,
    uint8 step,
    uint256 randShuffle,
    uint256 randOutcome
) internal returns (address[] memory) {

    uint256 n = playersInput.length;

    address[] memory shuffled = _shufflePlayers(playersInput, randShuffle);

    address[] memory winners = new address[](n / 2);
    address[] memory losers = new address[](n / 2);

    for (uint256 i = 0; i < n / 2; i++) {

        address p1 = shuffled[2 * i];
        address p2 = shuffled[2 * i + 1];

        uint256 entropy = uint256(
            keccak256(abi.encode(randOutcome, step, i, p1, p2))
        );

        if (entropy & 1 == 0) {
            winners[i] = p1;
            losers[i] = p2;
        } else {
            winners[i] = p2;
            losers[i] = p1;
        }
    }

    delete lastRoundWinners;
    delete lastRoundLosers;

    for (uint256 i = 0; i < winners.length; i++) {
        lastRoundWinners.push(winners[i]);
        lastRoundLosers.push(losers[i]);
    }

