    // ================= CLAIM =================

    // Anyone with a nonzero claimableBalance can withdraw it at any time,
    // independent of which cycle is currently running. Balances accumulate
    // across cycles if a claim isn't made right away (e.g. a champion from
    // cycle 5 and a failed-buyer refund from cycle 9 both sitting unclaimed
    // get swept out together in a single claim() call).
    function claim() external nonReentrant {
        uint256 amount = claimableBalance[msg.sender];
        require(amount > 0, "nothing claimable");

        claimableBalance[msg.sender] = 0;

        token.send(msg.sender, amount, "");

        emit Claimed(msg.sender, amount);
    }
}

