    delete sellers;
    delete buyers;
    delete postMarketFinalists;
    delete allLosers;
    delete failedBuyers;
    delete failedSellers;
    delete matchedBuyers;
    delete matchedSellers;
    delete lastRoundLosers;
    delete lastRoundWinners;
    delete semiFinalLosers;
    delete finalLosers;
    playersCount = 0;

    pool = 0;

    tradersReserve = 0;

    tradingDone = false;

    cycleId++;

    state = State.OPEN;
